// this is based on SendEmailMessage.
ParameterPage pp = tools.getParameterPage();

ClipboardPage emailAccount = null;

String accountName = pp.getString("pyNotifyAccountName");

if (! (accountName == null || accountName.isEmpty()))
{
  // attempt to open the account mentioned
  ParameterPage openParams = new ParameterPage();
  openParams.putString("AccountName", accountName);
  emailAccount = tools.findPage("D_pxEmailAccount", openParams);

  if (emailAccount != null && (emailAccount.hasMessages() || emailAccount.getString("pyAccountName").isEmpty()))
  {
    // load didn't work. Fallback on parameters.
    emailAccount = null;
  }
   else{
    ClipboardPage copy = tools.createPage("Data-EmailAccount","testEmailAccountPage");
    copy.putAll(emailAccount);
    //svcUtilsPriv.resolveGRSForEmailAccount(copy);
    emailAccount = copy;
}

}

// Send the email and check the status

PegaAPI pegaAPI = (PegaAPI)tools;
com.pega.pegarules.priv.util.ServiceUtilsPriv svcUtilsPriv = pegaAPI.getServiceUtilsPriv();
ClipboardPage response = null;

try {  	
    // use parameter page version of convert!
    java.util.Map<String, ClipboardPage> result = svcUtilsPriv.convertNotificationParamsForSend(tools, pp);
    ClipboardPage emailMessage = result.get(com.pega.pegarules.priv.util.ServiceUtilsPriv.EmailKey.EMAIL_MESSAGE);

    if (emailAccount == null)
    {
        emailAccount = result.get(com.pega.pegarules.priv.util.ServiceUtilsPriv.EmailKey.EMAIL_ACCOUNT);
    }

    if (emailMessage == null)
    {
        throw new PRRuntimeException("Parameters did not contain the required data for creating an Email Message record");
    }


    if (emailAccount == null)
    {
        throw new PRRuntimeException("Parameters did not contain the required data for creating an Email Account record");
    }

    response = pega_integrationengine_email.pxSendEmail(tools, emailAccount, emailMessage);
    if(response != null) {
        final String attachmentPageName = pp.getString("AttachmentPage");
        ClipboardProperty emailHeaders = null;
        final ClipboardPage attachmentPage = tools.findPage(attachmentPageName);
        if (attachmentPage != null)
        {
          emailHeaders = attachmentPage.getProperty("pyEmailHeaders");
        }

        if (emailHeaders != null) 
        {
            final ClipboardPage messageIDHeader = tools.createPage("Data-Email-Header", null);
            String messageID = response.getProperty("pyMessageId").getStringValue();
            messageIDHeader.putString("pyName", "Message-ID");
            messageIDHeader.putString("pyValue", messageID);
            if (oLog.isDebugEnabled()) 
            {
                oLog.debug("Message-ID:" + messageID);
            }
            emailHeaders.add(messageIDHeader);
        }

    }
} catch(Exception e) {

   oLog.error("Caught exception while sending email. Message may not have been sent.", e);
} 
finally 
{
    if(response != null) 
    {  // check for error message 
      String errormessage = response.getProperty("pyErrorMessage").getStringValue(); 
      if(errormessage.length()>0)
      {   
          Exception ex = new PRRuntimeException(errormessage);
          pp.putObject("EmailException",ex);
      }
        String clientResponse = response.getProperty("pyResponse").getStringValue();
        String debugInfo = response.getProperty("pyDebugInfo").getStringValue();
        if (oLog.isDebugEnabled())
        {
            oLog.debug("Response from email server:");
            oLog.debug(clientResponse);
            oLog.debug("java mail session debug payload:");
            oLog.debug(debugInfo);
        }
        if(pp != null) {
            pp.putString("pySMTPResponse", clientResponse);
            pp.putString("pySMTPDebugInfo", debugInfo);
            pp.putString("pyResponse", clientResponse);
            pp.putString("pyDebugInfo", debugInfo);
        }
    }
}
